    let importance = parts.next().and_then(parse_importance);
    match (category, importance, parts.next()) {
        (Some(c), Some(i), None) => (c, i),
        _ => (Category::Other, Importance::Skip),
    }
}

impl Guest for Node {
    fn run(item: FeedItem) -> Classification {
        enrich(&item.text);

        let prompt = format!(
            "id: {}\nfeed: {}\ntitle: {}\nlink: {}\npublished: {}\ntext:\n{}",
            bounded(&item.id, 200),
            bounded(&item.feed, 200),
